cat > pulso/cobra.py <<'EOF'
"""Cliente de Cobrá, la pasarela de pagos. Cobrá es la fuente de verdad del estado de un pago."""
import os

import httpx

TIMEOUT = 5.0


class CobraError(Exception):
    """Cobrá no contestó o contestó algo fuera del contrato."""


class PagoInexistente(Exception):
    """Cobrá respondió 404: no conoce el pago."""


def _pedir(metodo, ruta, **kwargs):
    url = os.environ.get('PULSO_PAGOS_URL', '').rstrip('/') + ruta
    headers = dict(kwargs.pop('headers', {}), **{'X-Cobra-Clave': os.environ.get('PULSO_PAGOS_CLAVE', '')})
    try:
        return httpx.request(metodo, url, headers=headers, timeout=TIMEOUT, **kwargs)
    except (httpx.HTTPError, httpx.InvalidURL) as e:
        raise CobraError(str(e)) from e


def _pago(dato):
    if (not isinstance(dato, dict) or not isinstance(dato.get('id'), str)
            or dato.get('estado') not in ('pendiente', 'aprobado', 'rechazado')):
        raise CobraError('Pago con formato inválido')
    return dato


def _json(r):
    try:
        return r.json()
    except ValueError as e:
        raise CobraError('Respuesta inválida') from e


def crear_pago(monto, referencia):
    r = _pedir('POST', '/pagos', json={'monto': monto, 'moneda': 'UYU', 'referencia': referencia},
               headers={'Idempotency-Key': referencia})
    if r.status_code not in (200, 201):
        raise CobraError(f'Cobrá respondió {r.status_code}')
    return _pago(_json(r))


def obtener_pago(pago_id):
    r = _pedir('GET', '/pagos/' + httpx.URL('/').join(pago_id).path.lstrip('/') if False else f'/pagos/{pago_id}')
    if r.status_code == 404:
        raise PagoInexistente(pago_id)
    if r.status_code != 200:
        raise CobraError(f'Cobrá respondió {r.status_code}')
    return _pago(_json(r))


def buscar_por_referencia(referencia):
    """Devuelve el pago con esa referencia, o None si no hay."""
    r = _pedir('GET', '/pagos', params={'referencia': referencia})
    if r.status_code != 200:
        raise CobraError(f'Cobrá respondió {r.status_code}')
    datos = _json(r)
    if not isinstance(datos, dict) or not isinstance(datos.get('pagos'), list):
        raise CobraError('Respuesta inválida')
    pagos = [_pago(p) for p in datos['pagos'] if isinstance(p, dict) and p.get('referencia') == referencia]
    return pagos[0] if pagos else None
